; //measuring the rising edges of the signal\nint Calc;\nint hallsensor = 2;    //The pin location of the sensor\n\nvoid rpm ()     //This is the function that the interupt calls\n{\n  NbTopsFan++;  //This function measures the rising and falling edge of the\n\nhall effect sensors signal\n}\n// The setup() method runs once, when the sketch starts\nvoid setup() //\n{\n  pinMode(hallsensor, INPUT); //initializes digital pin 2 as an input\n  Serial.begin(9600); //This is the setup function where the serial port is\n\ninitialised,\n  attachInterrupt(0, rpm, RISING); //and the interrupt is attached\n}\n// the loop() method runs over and over again,\n// as long as the Arduino has power\nvoid loop ()\n{\n  NbTopsFan = 0;   //Set NbTops to 0 ready for calculations\n  sei();      //Enables interrupts\n  delay (1000);   //Wait 1 second\n  cli();      //Disable interrupts\n  Calc = (NbTopsFan * 60 / 7.5); //(Pulse frequency x 60) / 7.5Q, = flow rate\n\nin L/hour\n  Serial.print (Calc, DEC); //Prints the number calculated above\n  Serial.print (" L/hour\\r\\n"); //Prints "L/hour" and returns a  new line\n}\n'})}),"\n",(0,i.jsx)(s.p,{children:"Puedes consultar nuestro foro para m\xe1s detalles sobre la lectura del caudal con el sensor de flujo de agua."}),"\n",(0,i.jsx)(s.h2,{id:"diagrama-de-conexiones",children:"Diagrama de Conexiones"}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsxs)(s.p,{children:["El di\xe1metro externo de rosca para las conexiones es de 1.4 mm.\n",(0,i.jsx)(s.img,{src:"https://files.seeedstudio.com/wiki/G1_and_2_inch_Water_Flow_Sensor/img/Wfs-wiring.jpg",alt:""})]}),"\n",(0,i.jsx)(s.h2,{id:"tabla-de-salida",children:"Tabla de Salida"}),"\n",(0,i.jsx)(s.hr,{}),"\n",(0,i.jsx)(s.p,{children:"Frecuencia de pulso (Hz) en prueba horizontal = 7.5 \xd7 Q, donde Q es el caudal en L/min. (Resultados con un margen de \xb1 3%)"}),"\n",(0,i.jsxs)(s.table,{children:[(0,i.jsx)(s.thead,{children:(0,i.jsxs)(s.tr,{children:[(0,i.jsx)(s.th,{children:"\xcdtem"}),(0,i.jsx)(s.th,{childr